input.command:
EV=$(mktemp -d /tmp/kk-review-evidence-XXXXXX) && git diff --cached > "$EV/staged.patch" && mkdir -p "$EV/historical" && git show HEAD:routes.py > "$EV/historical/routes.py" && BLOB=$(git rev-parse HEAD:routes.py) && cat > "$EV/historical/manifest.json" <<EOF
{
  "repository": "$(pwd)",
  "revision": "$(git rev-parse HEAD)",
  "items": [
    {"original_path": "routes.py", "blob": "$BLOB", "line_span": "1-$(wc -l < "$EV/historical/routes.py")", "omitted": "none", "file": "$EV/historical/routes.py"}
  ]
}
EOF
chmod -R a-w "$EV/historical" && echo "$EV" && cat "$EV/historical/manifest.json" && git diff --quiet -- preview.py routes.py && echo "worktree == index for changed files"
